-- ---------------------------------------------------------------------
-- migration: 009_admin_password_reset.sql
-- ---------------------------------------------------------------------
-- Migration 009: admin password reset support.
--
-- Adds the columns the forgot-password flow uses. We store the bcrypt hash
-- of the random token (never the token itself) plus a hard expiry. On a
-- POST /auth/reset-password we look up the admin whose `expires_at` is in
-- the future and whose stored hash matches the supplied token; on use, the
-- columns are cleared so the token cannot be replayed.
--
-- Sub admins are deliberately NOT given the same flow — they get the
-- "contact your administrator" message because their account is created and
-- managed by the admin, not self-service.

ALTER TABLE admins
  ADD COLUMN password_reset_token_hash VARCHAR(255) NULL AFTER password_hash,
  ADD COLUMN password_reset_expires_at DATETIME NULL AFTER password_reset_token_hash,
  ADD KEY ix_admins_reset_expires (password_reset_expires_at);


-- ---------------------------------------------------------------------
-- migration: 010_admin_password_reset_via_otp.sql
-- ---------------------------------------------------------------------
-- Migration 010: drop the magic-link reset columns added in 009.
--
-- The admin forgot-password flow now uses a 6-digit email OTP via the shared
-- `otp_codes` table (purpose='admin_password_reset'), same channel and same
-- service as buyer/seller verification. The dedicated columns on `admins`
-- are no longer read or written by any code path.

ALTER TABLE admins
  DROP KEY ix_admins_reset_expires,
  DROP COLUMN password_reset_expires_at,
  DROP COLUMN password_reset_token_hash;


-- ---------------------------------------------------------------------
-- migration: 011_inventory_details_json.sql
-- ---------------------------------------------------------------------
-- Migration 011: tabbed inventory registration form.
--
-- The new admin inventory form captures dozens of category-specific fields
-- (flat-only floor/lift; plot-only zoning/frontage; hostel-only room count;
-- land-only zone/variety; etc.). Adding ~120 nullable columns would be
-- painful to evolve and most rows would be empty for any given category.
--
-- Instead we keep the small set of common, queryable fields as columns
-- (code, title, type, txn, status, location, bhk, area, price, owner, agent)
-- and stash the long tail in a single JSON column. Querying inside `details`
-- is rare; when it's needed MySQL's JSON functions handle it.
--
-- Going JSON also means future field additions don't need a migration — only
-- a frontend change and an updated Joi schema.

ALTER TABLE inventory_properties
  ADD COLUMN details JSON NULL AFTER agent_contact;


-- ---------------------------------------------------------------------
-- migration: 012_property_categories_seed.sql
-- ---------------------------------------------------------------------
-- Migration 012: seed the property-category codes the new tabbed inventory
-- form uses. The form's outer tabs match the registration-form folders the
-- client supplied:
--   Flat, Bunglow, Plot, Shop, Land, Commercial, Hostel, Paying Guest.
--
-- Codes are inserted with INSERT IGNORE so this is safe to re-run and won't
-- clobber any label/sort_order tweaks the admin has already made via the
-- Masters UI.

INSERT IGNORE INTO master_property_types (code, label, sort_order, is_active) VALUES
  ('flat',          'Flat',          10, 1),
  ('bunglow',       'Bunglow',       20, 1),
  ('plot',          'Plot',          30, 1),
  ('shop',          'Shop',          40, 1),
  ('land',          'Land',          50, 1),
  ('commercial',    'Commercial',    60, 1),
  ('hostel',        'Hostel',        70, 1),
  ('paying_guest',  'Paying Guest',  80, 1);


-- ---------------------------------------------------------------------
-- migration: 013_website_properties_details_json.sql
-- ---------------------------------------------------------------------
-- Migration 013: details JSON on website_properties.
--
-- Mirrors the column added to inventory_properties in migration 011 so both
-- property tables can carry the same open-ended extras (map coordinates,
-- amenities, etc.). On website_properties this primarily holds lat/lng for
-- the public detail page's map, but any category-specific fields the admin
-- captures during review can also live here.

ALTER TABLE website_properties
  ADD COLUMN details JSON NULL AFTER rejection_reason;


-- ---------------------------------------------------------------------
-- migration: 014_inventory_status_note.sql
-- ---------------------------------------------------------------------
-- Migration 014: status-change note + audit on inventory_properties.
--
-- When an admin moves a property's status (e.g. "Available" → "Booked",
-- "Hold" → "Sold"), the listing UI now prompts for a free-text note so the
-- team can capture the *why*: which buyer placed the hold, what fell through,
-- expected re-listing date, etc.
--
-- We store only the LATEST note on the row (status_note) plus a small audit
-- pair (when + which admin). Full history is not a current requirement and
-- would need its own table — keeping this single-row for now per the project's
-- "don't design for hypothetical future requirements" rule.

ALTER TABLE inventory_properties
  ADD COLUMN status_note        TEXT             NULL AFTER status,
  ADD COLUMN status_changed_at  DATETIME         NULL AFTER status_note,
  ADD COLUMN status_changed_by  BIGINT UNSIGNED  NULL AFTER status_changed_at;


-- ---------------------------------------------------------------------
-- migration: 015_property_files_amenity_kind.sql
-- ---------------------------------------------------------------------
-- Migration 015: allow 'amenity' as a file_kind on property_files.
--
-- Sellers now attach a thumbnail image to each amenity they list
-- ("Parking", "Lift", "Modular Kitchen", etc.). Those images live in the
-- same uploads directory as property gallery images but need to be
-- distinguishable from cover/gallery photos so:
--   - the listing detail page doesn't render them in the main gallery,
--   - the storage quota still accounts for them,
--   - delete-property still cascades them.
--
-- The amenity's typed *label* is stored in `original_name` (a free-text
-- column that already holds the user-supplied filename — repurposing it for
-- the amenity label keeps the schema change to a one-line ENUM extension).

ALTER TABLE property_files
  MODIFY COLUMN file_kind ENUM('image', 'document', 'amenity') NOT NULL;


-- ---------------------------------------------------------------------
-- migration: 016_seed_transaction_type_variants.sql
-- ---------------------------------------------------------------------
-- Migration 016: seed the full set of transaction-type tabs the admin
-- inventory form expects.
--
-- The reference Flat / Bunglow / Plot / Shop / Land / Commercial / Hostel
-- registration forms split the workflow into seven flavours:
--   sale  — Re-sale of an existing unit
--   purchase — Buyer-side (admin recording a buyer wish-list)
--   rent_in  — Tenant-side (admin recording a renter wish-list)
--   rent_out — Owner letting a unit on rent
--   lease_in — Tenant-side lease (long term)
--   lease_out — Owner leasing a unit out
--   joint_venture — Flat-specific owner/developer arrangement
--
-- We keep the legacy `rent` and `lease` rows around (older listings still
-- reference them) but mark them `is_active = 0` so they no longer surface as
-- tabs in the new form. Existing rows pointing at those codes keep working.

INSERT INTO master_transaction_types (code, label, sort_order, is_active)
VALUES
  ('purchase',       'Purchase',       15, 1),
  ('rent_in',        'Rent In',        21, 1),
  ('rent_out',       'Rent Out',       22, 1),
  ('lease_in',       'Lease In',       31, 1),
  ('lease_out',      'Lease Out',      32, 1),
  ('joint_venture',  'Joint Venture',  40, 1)
ON DUPLICATE KEY UPDATE
  label = VALUES(label),
  sort_order = VALUES(sort_order),
  is_active = 1;

-- Retire the legacy generic codes so they stop showing as duplicate tabs.
-- Listings already saved with these codes keep working — only the picker UI
-- changes. Re-enable manually from /admin/masters/transaction_type if needed.
UPDATE master_transaction_types SET is_active = 0 WHERE code IN ('rent', 'lease');


-- ---------------------------------------------------------------------
-- migration: 017_idempotency_keys.sql
-- ---------------------------------------------------------------------
-- Migration 017: idempotency key cache.
--
-- When a state-mutating endpoint receives a request with an
-- `Idempotency-Key` header, the middleware stores the full response under
-- that key. A duplicate request (same key) replays the cached response
-- instead of running the handler again — preventing duplicate leads,
-- duplicate property creates, duplicate approvals, etc. from rapid
-- double-clicks, browser-back-resubmits, or flaky-network retries.
--
-- The key is scoped by route (method + path) AND by the caller (auth
-- subject when present, IP when public) so two different users can't
-- accidentally collide on the same client-generated UUID.
--
-- Rows older than the TTL are purged by a cron-driven endpoint — see
-- Deployment notes in CLAUDE.md (no setInterval / setTimeout in the app).

CREATE TABLE idempotency_keys (
  id            BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  idempotency_key VARCHAR(128)  NOT NULL,
  scope         VARCHAR(255)    NOT NULL,            -- method + path + actor
  status_code   SMALLINT UNSIGNED NOT NULL,
  response_body MEDIUMTEXT      NULL,                -- JSON body
  created_at    DATETIME        NOT NULL DEFAULT CURRENT_TIMESTAMP,

  PRIMARY KEY (id),
  UNIQUE KEY uq_idempotency_key_scope (idempotency_key, scope),
  KEY ix_idempotency_created_at (created_at)
) ENGINE = InnoDB DEFAULT CHARSET = utf8mb4;


-- ---------------------------------------------------------------------
-- migration: 018_lead_pipeline_and_assignment.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 018 — Lead pipeline (more granular statuses) + lead assignment
-- ===========================================================
-- 1. Extends `leads.status` from ('new', 'contacted') to a full sales
--    pipeline: new → contacted → site_visit → closed_won / closed_lost.
--    Old rows keep their value (both 'new' and 'contacted' remain valid).
-- 2. Adds `assigned_sub_admin_id` — nullable FK into sub_admins. The head
--    admin sees all leads by default and doesn't need to be "assigned";
--    assignment is the mechanism for routing leads to specific sub-admins.
--    NULL means "unassigned, head admin handles it".
-- 3. Adds index on (status, assigned_sub_admin_id) so the Kanban board can
--    pull "my open leads in column X" without a table scan.
-- ===========================================================

ALTER TABLE leads
  MODIFY COLUMN status ENUM('new', 'contacted', 'site_visit', 'closed_won', 'closed_lost')
    NOT NULL DEFAULT 'new';

ALTER TABLE leads
  ADD COLUMN assigned_sub_admin_id BIGINT UNSIGNED NULL AFTER status,
  ADD CONSTRAINT fk_leads_assigned_sub_admin
    FOREIGN KEY (assigned_sub_admin_id) REFERENCES sub_admins(id) ON DELETE SET NULL,
  ADD KEY ix_leads_status_assigned (status, assigned_sub_admin_id);


-- ---------------------------------------------------------------------
-- migration: 019_website_property_view_count.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 019 — Per-property view count (seller analytics)
-- ===========================================================
-- Adds a denormalized `view_count` column on website_properties. Each
-- public-website detail fetch (`GET /api/public/properties/:identifier`)
-- bumps this counter by 1 via a simple UPDATE. A dedicated counter column
-- is cheaper than a per-view audit row and good enough for the seller's
-- "your listing has been viewed N times" widget.
--
-- Bot-filtering / unique-visitor dedup is deliberately out of scope for
-- this MVP — we surface raw page-load counts. If/when real analytics are
-- needed, fold it through a property_views table instead.
-- ===========================================================

ALTER TABLE website_properties
  ADD COLUMN view_count BIGINT UNSIGNED NOT NULL DEFAULT 0 AFTER is_featured;


-- ---------------------------------------------------------------------
-- migration: 020_audit_log.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 020 — Admin audit log
-- ===========================================================
-- Records who did what to which resource. Lightweight append-only table —
-- writes are fire-and-forget from the service layer (a failure here MUST
-- never block the actual mutation).
--
-- Schema:
--   actor_type      'admin' | 'sub_admin'      (matches the JWT role)
--   actor_id        the head admin id or sub-admin id
--   actor_name      cached at write time so the log still reads cleanly
--                   even if the user is later renamed or soft-deleted
--   action          short verb, e.g. 'lead.status.changed',
--                   'property.approved', 'sub_admin.created'
--   entity_type     the resource kind, e.g. 'lead', 'website_property',
--                   'inventory_property', 'sub_admin', 'cms.banner'
--   entity_id       PK of the affected row (BIGINT)
--   summary         human-readable one-liner for the UI list
--   metadata        JSON bag of structured before/after diffs etc.
--   created_at      DATETIME, append-only
-- ===========================================================

CREATE TABLE IF NOT EXISTS audit_log (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  actor_type ENUM('admin', 'sub_admin') NOT NULL,
  actor_id BIGINT UNSIGNED NOT NULL,
  actor_name VARCHAR(255) NULL,
  action VARCHAR(64) NOT NULL,
  entity_type VARCHAR(64) NOT NULL,
  entity_id BIGINT UNSIGNED NULL,
  summary VARCHAR(500) NULL,
  metadata JSON NULL,
  ip_address VARCHAR(45) NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  KEY ix_audit_log_created_at (created_at),
  KEY ix_audit_log_entity (entity_type, entity_id),
  KEY ix_audit_log_actor (actor_type, actor_id),
  KEY ix_audit_log_action (action)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- migration: 021_reactivate_rent_lease_transaction_types.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 021 — Reactivate the public-facing 'rent' and 'lease' transaction codes
-- ===========================================================
-- Migration 016 retired `rent` and `lease` from the masters table on the
-- assumption that the granular variants (`rent_in` / `rent_out` /
-- `lease_in` / `lease_out`) would replace them everywhere. But the public
-- website and the seller's Post Property form still use the simpler
-- 3-code model (sale / rent / lease) — and the PRD locks that model as
-- the buyer-facing categorization. With `rent` / `lease` inactive, every
-- new seller submission fails master validation:
--
--   "Unknown or inactive transaction type: \"rent\""
--
-- This migration just flips them back to active. The granular admin-only
-- variants stay active — both shapes coexist (admins can use either when
-- recording inventory; sellers only ever see the simple three).
-- ===========================================================

UPDATE master_transaction_types
   SET is_active = 1
 WHERE code IN ('rent', 'lease');


-- ---------------------------------------------------------------------
-- migration: 022_notification_targets.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 022 — Per-user targeted notifications
-- ===========================================================
-- The original notifications table was broadcast-by-module only: every
-- sub-admin with the matching module sees every notification under that
-- module. Lead assignment needs the opposite — notify ONE specific
-- sub-admin that they were just handed a lead.
--
-- Adds two columns:
--   target_actor_type ENUM('admin', 'sub_admin') NULL
--   target_actor_id   BIGINT UNSIGNED            NULL
-- When both are set, the notification is private to that actor — list /
-- unreadCount queries scope accordingly. When both NULL, behaviour is the
-- legacy broadcast-by-module flow (no change to existing rows).
-- ===========================================================

ALTER TABLE notifications
  ADD COLUMN target_actor_type ENUM('admin', 'sub_admin') NULL AFTER module_key,
  ADD COLUMN target_actor_id   BIGINT UNSIGNED            NULL AFTER target_actor_type,
  ADD KEY ix_notifications_target (target_actor_type, target_actor_id);


-- ---------------------------------------------------------------------
-- migration: 023_leads_closed_reason.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 023 — Why a lead was closed
-- ===========================================================
-- When a lead reaches closed_won we auto-close every other open lead on
-- the same property as closed_lost (see closeSiblingsAsLost). Those auto-
-- closed rows are indistinguishable from leads an admin closed by hand,
-- which is confusing on the Kanban — admins see a "lost" card and wonder
-- why nobody touched it.
--
-- This column stores the reason. NULL means "closed by admin action"
-- (the default and historical behaviour). 'sibling_won' is set by the
-- auto-close cascade. Cheap to extend later for other automated reasons
-- ('property_deleted', 'duplicate_buyer', etc.) without another migration.
-- ===========================================================

ALTER TABLE leads
  ADD COLUMN closed_reason VARCHAR(32) NULL AFTER status;


-- ---------------------------------------------------------------------
-- migration: 024_refresh_tokens_seller_subject.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 024 — Allow sellers in refresh_tokens.subject_kind
-- ===========================================================
-- Sellers log in via OTP and get an access token, but the original
-- schema only knew about ('admin', 'sub_admin') subjects. Without a
-- seller refresh token, the seller's session dies on every page reload
-- (no cookie to silently refresh from), forcing them through OTP again.
--
-- Extending the ENUM is non-destructive — existing rows keep their
-- current values, and seller-issued rows can now coexist.
-- ===========================================================

ALTER TABLE refresh_tokens
  MODIFY COLUMN subject_kind ENUM('admin', 'sub_admin', 'seller') NOT NULL;


-- ---------------------------------------------------------------------
-- migration: 025_cms_sidebar_ads.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- Migration 025: CMS-managed sidebar advertisement.
--
-- Powers the <StickySidebarAd /> right-column promo on the public
-- website. The public endpoint returns ONE active row per request
-- (newest active, within the start/end date window). If no row
-- qualifies, the website falls back to a static promo — the slot
-- is never empty, so admin downtime never affects the page.
--
-- Columns mirror the fields the admin form exposes
-- (Frontend/src/admin/pages/Cms/SidebarAdsList.jsx). Image lives on
-- disk via the existing cms upload pipeline (uploads/public/cms/),
-- so we only store the URL — same pattern as cms_banners.
-- ===========================================================

CREATE TABLE IF NOT EXISTS cms_sidebar_ads (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  image_url VARCHAR(512) NULL,
  title VARCHAR(120) NOT NULL,
  subtitle VARCHAR(240) NULL,
  cta_text VARCHAR(60) NULL,
  cta_url VARCHAR(500) NULL,
  start_date DATE NULL,
  end_date DATE NULL,
  sort_order INT NOT NULL DEFAULT 0,
  is_active TINYINT(1) NOT NULL DEFAULT 1,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  PRIMARY KEY (id),
  -- Active-window lookup is the hot path: the public endpoint scans
  -- this table on every visitor hit. Index the columns it filters /
  -- orders on so the query stays O(log n) as the table grows.
  KEY ix_cms_sidebar_ads_active_window (is_active, start_date, end_date, sort_order)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- migration: 026_inventory_lookup_masters.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 026 — Generic master_lookups table + Phase-1 seed
-- ===========================================================
-- The existing four master_* tables (property_types, transaction_types,
-- flat_types, status_types) hold lookups that are tightly coupled to
-- inventory_properties columns. The reference registration forms (Flat,
-- Bunglow, Plot, Land, Shop, Commercial, Hostel, PG, Hospital, Industrial,
-- SEZ, TDR, Pre-Leased, Bank Auction) reference 30+ additional vocabularies
-- (Floor, Facing, Plot Type, Lease Period, Bank Name, Phase, Wing, Possession
-- Month / Year, Tenant Preference, Hospital Type, …) — all simple key/label
-- lookups that don't justify a table each.
--
-- One generic table with a `master_key` discriminator keeps the cost of a
-- new vocabulary down to "insert seed rows", lets the admin manage every
-- one through the existing generic /admin/masters/:key UI, and avoids 30
-- near-identical CREATE TABLE blocks. The optional `parent_code` column
-- supports hierarchical masters (district → taluka → shivar) without a
-- second table.
--
-- The existing four master_* tables are NOT migrated — they stay because
-- inventory_properties.{property_type, transaction_type, bhk, status}
-- already references them via the masters service. New vocabularies go
-- here; existing ones stay where they are.
-- ===========================================================

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS master_lookups (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  master_key  VARCHAR(64)  NOT NULL,
  code        VARCHAR(64)  NOT NULL,
  label       VARCHAR(255) NOT NULL,
  parent_code VARCHAR(64)  NULL,
  sort_order  INT          NOT NULL DEFAULT 0,
  is_active   TINYINT(1)   NOT NULL DEFAULT 1,
  created_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at  DATETIME     NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted_at  DATETIME     NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uk_master_lookups_key_code (master_key, code),
  KEY ix_master_lookups_key_active (master_key, is_active, sort_order),
  KEY ix_master_lookups_parent (master_key, parent_code)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

