-- ---------------------------------------------------------------------
-- migration: 048_enquiry_properties.sql
-- ---------------------------------------------------------------------
-- ============================================================
-- 048 — Enquiry properties (parallel to inventory_properties)
-- ============================================================
-- The 79 registration forms split into two admin-facing surfaces:
--
--   Inventory Forms  (22 forms — Out / Lease-Out / Rent-Out / Joint Venture)
--   Enquiry Forms    (57 forms — In / Purchase / Sale / Rent-In / Lease-In /
--                                Rate Finder / TDR / Bank Auction / etc.)
--
-- Requirement: both surfaces are fully independent modules — separate tables,
-- separate APIs, no cross-navigation. This migration adds the storage side.
--
-- `enquiry_properties` is a structural mirror of `inventory_properties` after
-- migrations 004 / 011 / 014 / 027 (all the ALTERs applied). Same columns,
-- same indexes, same FK to admins.
--
-- Data migration (moving Enquiry-category rows out of inventory_properties)
-- ships as a separate one-shot script (scripts/migrate-inventory-to-enquiry.js)
-- so it can be dry-run first and rolled back per admin ask.
-- ============================================================

SET NAMES utf8mb4;

-- ------------------------------------------------------------
-- Enquiry properties table (mirror of inventory_properties)
-- ------------------------------------------------------------
CREATE TABLE IF NOT EXISTS enquiry_properties (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  property_code VARCHAR(32) NOT NULL,
  registration_date DATE NULL,
  title VARCHAR(255) NOT NULL,
  description TEXT NULL,
  property_type VARCHAR(64) NOT NULL,
  transaction_type ENUM('sale', 'rent', 'lease') NOT NULL,
  transaction_variant VARCHAR(64) NULL,
  location VARCHAR(255) NOT NULL,
  district VARCHAR(64) NULL,
  taluka VARCHAR(64) NULL,
  shivar VARCHAR(64) NULL,
  latitude DECIMAL(10,7) NULL,
  longitude DECIMAL(10,7) NULL,
  pincode VARCHAR(10) NULL,
  area_value DECIMAL(12,2) NULL,
  area_unit VARCHAR(16) NULL,
  bhk VARCHAR(16) NULL,
  price DECIMAL(14,2) NOT NULL,
  status ENUM('available', 'sold', 'rented', 'inactive') NOT NULL DEFAULT 'available',
  status_note TEXT NULL,
  status_changed_at DATETIME NULL,
  status_changed_by BIGINT UNSIGNED NULL,
  is_draft TINYINT(1) NOT NULL DEFAULT 0,
  owner_name VARCHAR(255) NULL,
  owner_contact VARCHAR(20) NULL,
  agent_name VARCHAR(255) NULL,
  agent_contact VARCHAR(20) NULL,
  details JSON NULL,
  created_by_admin_id BIGINT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted_at DATETIME NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uk_enquiry_property_code (property_code),
  KEY ix_enquiry_location (location),
  KEY ix_enquiry_property_type (property_type),
  KEY ix_enquiry_transaction_type (transaction_type),
  KEY ix_enquiry_transaction_variant (transaction_variant),
  KEY ix_enquiry_status (status),
  KEY ix_enquiry_is_draft (is_draft),
  KEY ix_enquiry_district_taluka (district, taluka),
  KEY ix_enquiry_pincode (pincode),
  KEY ix_enquiry_created_at (created_at),
  CONSTRAINT fk_enquiry_admin FOREIGN KEY (created_by_admin_id) REFERENCES admins (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- ------------------------------------------------------------
-- Extend property_files.property_kind to include 'enquiry'.
-- Property images + private documents for enquiry rows go through the same
-- shared property_files table (identical policy: public images, private docs,
-- storage-usage tracking). The service layer already parametrises on
-- propertyKind — only the ENUM needs widening.
--
-- Idempotent guard: MODIFY COLUMN with the same set of values is a no-op if
-- 'enquiry' is already listed, so re-running this migration is safe.
-- ------------------------------------------------------------
ALTER TABLE property_files
  MODIFY COLUMN property_kind ENUM('inventory', 'website', 'enquiry') NOT NULL;


-- ---------------------------------------------------------------------
-- migration: 049_location_masters_columns.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 049 — Location cascade: state_code / state_name / pincode
--        columns + hierarchy indexes for master_lookups
-- ===========================================================
-- The district → taluka → shivar (village) cascade already lives in
-- `master_lookups` (see migration 026): each row's `parent_code` points
-- at its parent's `code`. Everything the Maharashtra 7/12 portal-style
-- cascade needs is already there — code + label + parent_code — except
-- three government-master fields we want to carry alongside imported
-- data so admins can see and search on them:
--
--   - `state_code`  numeric state code (only meaningful on `district` rows)
--   - `state_name`  english state name (mirror of state_code, for display)
--   - `pincode`     6-digit Indian pincode (only meaningful on `shivar` rows)
--
-- All three are NULL for pre-existing lookup vocabularies. The CSV import
-- script (`scripts/import-locations.js`) is the only writer that populates
-- them today; the admin master CRUD leaves them alone and admins can still
-- Add/Edit/Delete districts/talukas/villages through the existing UI (they
-- just won't set state / pincode when adding manually — which is fine, both
-- fields are nullable).
--
-- Indexes: the existing `ix_master_lookups_parent (master_key, parent_code)`
-- is already ideal for the cascade query pattern (SELECT ... WHERE
-- master_key='taluka' AND parent_code='<districtCode>'). We just add
-- `(master_key, is_active, label)` — the paginated + searchable village
-- lookup does WHERE master_key='shivar' AND is_active=1 AND label LIKE ?
-- ORDER BY label, and 45k rows without this index would be a full scan.

SET NAMES utf8mb4;

ALTER TABLE master_lookups
  ADD COLUMN state_code  VARCHAR(10)  NULL AFTER parent_code,
  ADD COLUMN state_name  VARCHAR(120) NULL AFTER state_code,
  ADD COLUMN pincode     VARCHAR(10)  NULL AFTER state_name;

-- Composite index for the village-search query pattern (label prefix filter
-- + alphabetical order under a specific master_key + active state). Also
-- accelerates the districts alphabetical listing.
ALTER TABLE master_lookups
  ADD KEY ix_master_lookups_key_active_label (master_key, is_active, label);

-- Composite index for the parent-cascade + label filter (talukas/villages
-- filtered by parent AND searched by label).
ALTER TABLE master_lookups
  ADD KEY ix_master_lookups_key_parent_label (master_key, parent_code, label);

-- Pincode lookups (used by the "villages inside a pincode" reverse search
-- if we ever expose it — cheap to add now).
ALTER TABLE master_lookups
  ADD KEY ix_master_lookups_pincode (pincode);


-- ---------------------------------------------------------------------
-- migration: 050_business_associates.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 050 — Business Associates Database
-- ===========================================================
-- Directory of clients / business associates the office works with.
-- Powers the Admin → Business Associates CRUD and the public
-- homepage strip (`/api/public/business-associates`).
--
-- Location fields piggy-back on the existing global masters:
--   district_code → master_lookups.master_key = 'district'
--   taluka_code   → master_lookups.master_key = 'taluka'
--   city_code     → master_lookups.master_key = 'shivar' (smallest unit)
-- The frontend form uses the same LocationCascade component as the
-- Land Records surface; city == shivar here — the admin form just
-- relabels the last dropdown "City" for this use case.
--
-- No unique-key constraint on mobile / email — a single associate can
-- have multiple contacts, and multiple entries may legitimately share
-- an email (e.g. two people at the same firm). Duplicate detection is
-- a UX concern, not a DB constraint.
-- ===========================================================

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS business_associates (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  salutation    ENUM('mr','mrs','miss','smt') NOT NULL,
  first_name    VARCHAR(100) NOT NULL,
  middle_name   VARCHAR(100) NULL,
  surname       VARCHAR(100) NULL,
  designation   VARCHAR(200) NULL,
  address_line1 VARCHAR(255) NULL,
  address_line2 VARCHAR(255) NULL,
  city_code     VARCHAR(64)  NULL,
  taluka_code   VARCHAR(64)  NULL,
  district_code VARCHAR(64)  NULL,
  phone1        VARCHAR(20)  NULL,
  phone2        VARCHAR(20)  NULL,
  mobile1       VARCHAR(20)  NULL,
  mobile2       VARCHAR(20)  NULL,
  mobile3       VARCHAR(20)  NULL,
  whatsapp      VARCHAR(20)  NULL,
  email1        VARCHAR(255) NULL,
  email2        VARCHAR(255) NULL,
  website1      VARCHAR(255) NULL,
  website2      VARCHAR(255) NULL,
  date_of_birth DATE NULL,
  created_by_admin_id BIGINT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted_at DATETIME NULL,
  PRIMARY KEY (id),
  KEY ix_biz_assoc_district (district_code),
  KEY ix_biz_assoc_taluka   (taluka_code),
  KEY ix_biz_assoc_city     (city_code),
  KEY ix_biz_assoc_created  (created_at),
  -- Contact-lookup helpers for the list-page search.
  KEY ix_biz_assoc_mobile1  (mobile1),
  KEY ix_biz_assoc_email1   (email1),
  CONSTRAINT fk_biz_assoc_admin FOREIGN KEY (created_by_admin_id) REFERENCES admins (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


