-- ---------------------------------------------------------------------
-- migration: 056_property_status_dynamic.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 056 — Property Status: dynamic master (drop ENUM lock)
-- ===========================================================
-- The `status_type` master + `master_status_types` table already exist
-- (created + seeded in migration 008 with Available / Sold / Rented /
-- Inactive). Two changes are needed to make Property Status a fully
-- admin-editable Global master:
--
-- 1. Widen the status columns from ENUM(...) to VARCHAR(64) on the
--    property tables. The current ENUM is a hard database-level lock
--    that rejects any new master value (e.g. "Reserved") before the
--    row hits the app-layer validator. VARCHAR + master validation is
--    the same shape every other lookup uses (property_type,
--    transaction_type, district, etc.). Existing rows keep their
--    current string values — ENUM → VARCHAR is a lossless conversion
--    in MySQL, no backfill needed.
--
-- 2. Un-fixing the master + renaming the label happens in
--    server/services/masters/management.js (removes 'status_type' from
--    FIXED_MASTERS + updates MASTER_LABELS). No table-level change
--    there.
--
-- Historical rows continue to render correctly: their existing status
-- codes ('available' / 'sold' / 'rented' / 'inactive') match seeded
-- master rows, so the frontend label lookup resolves as before.
-- ===========================================================

ALTER TABLE inventory_properties
  MODIFY COLUMN status VARCHAR(64) NOT NULL DEFAULT 'available';

ALTER TABLE enquiry_properties
  MODIFY COLUMN status VARCHAR(64) NOT NULL DEFAULT 'available';


-- ---------------------------------------------------------------------
-- migration: 056_website_properties_location_columns.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 056 — Website properties: hierarchical location columns
-- ===========================================================
-- The Website Properties admin surface needs to filter by the same
-- District → Taluka → Village (shivar) cascade the Inventory list uses.
-- Until now, `website_properties` stored only a single free-text
-- `location` string produced by the public seller form's map picker,
-- so a code-level location filter was impossible.
--
-- Mirror migration 027's shape for `inventory_properties`: nullable
-- master-code columns + a composite (district, taluka) index and a
-- pincode index. Existing rows keep NULL until re-edited; the new
-- district/taluka/village cascade added to the public AddPropertyPage
-- captures these values on new submissions.

ALTER TABLE website_properties
  ADD COLUMN district VARCHAR(64) NULL AFTER location,
  ADD COLUMN taluka   VARCHAR(64) NULL AFTER district,
  ADD COLUMN shivar   VARCHAR(64) NULL AFTER taluka,
  ADD COLUMN pincode  VARCHAR(10) NULL AFTER shivar;

ALTER TABLE website_properties
  ADD KEY ix_website_district_taluka (district, taluka),
  ADD KEY ix_website_shivar          (shivar),
  ADD KEY ix_website_pincode         (pincode);


-- ---------------------------------------------------------------------
-- migration: 057_master_description_and_status_deps.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 057 - Master description column + Property Status full CRUD parity
-- ===========================================================
-- T-2026-045: Global / Property Status master becomes fully editable
-- (parity with Property Type / Transaction Type / Property Variety).
-- The backend-side lock (FIXED_MASTERS set) was already cleared in
-- migration 056. Two additive changes finish the job:
--
-- 1. Add an optional `description` column to `master_status_types` so
--    admins can annotate what each status means (e.g. "Reserved -
--    kept aside for a buyer with token amount"). Description is
--    OPTIONAL, VARCHAR(255), NULL by default. Only status_type gets
--    the column; other masters stay lean.
--
-- 2. No seed changes. The four seeded default rows (available / sold
--    / rented / inactive) stay as-is with NULL descriptions.
--
-- Historical rows are unaffected. Backend serializer (toDto) begins
-- surfacing the field once this migration is applied.
-- ===========================================================

ALTER TABLE master_status_types
  ADD COLUMN description VARCHAR(255) NULL AFTER label;


-- ---------------------------------------------------------------------
-- migration: 058_property_type_master_reseed.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 058  Global / Property Type: reseed to the 16 authoritative values
-- ===========================================================
-- T-2026-046: The Global / Property Type master must contain EXACTLY
-- these 16 values (and only these) as the single source of truth for
-- every Inventory Property Type dropdown across the app:
--
--   Bank Auction, Bungalow, Commercial Space, Flat, Hospital, Hostel,
--   Hotel, Industrial Plot, Land, Plot, Pre-Leased Property, Project
--   Registration, SEZ Land, SEZ Plot, Shop, TDR
--
-- The master already exists (created in migration 008, seeded in
-- migrations 008 / 012 / 028). It is currently CRUD-editable
-- (FIXED_MASTERS is empty in server/services/masters/management.js).
-- Two operations required, both idempotent:
--
--   1. Deactivate every existing row whose code is NOT in the
--      authoritative list. We SOFT-DELETE (deleted_at = NOW,
--      is_active = 0) rather than hard-delete because inventory /
--      enquiry / website property rows may still reference legacy
--      codes (e.g. flat, house, villa, plot, commercial,
--      agricultural, other  from migration 008). This mirrors the
--      pattern used by the Property Status master (migration 056/057)
--      which preserves historical data.
--
--   2. INSERT-or-UPDATE the 16 authoritative rows (upsert by code).
--      If any code was previously soft-deleted (e.g. bank_auction from
--      migration 028), we revive it in-place  clear deleted_at, set
--      is_active = 1, refresh label / sort_order. This preserves the
--      row id + audit history.
--
-- Codes follow the existing masters convention (snake-case, lower).
-- Sort order runs 10..160 alphabetically per the spec sentence
-- order.
--
-- IMPORTANT: This migration touches ONLY the master_property_types
-- table. It does NOT alter inventory / enquiry / website records. If
-- an existing property row stores a legacy code like 'agricultural',
-- that row remains intact  the frontend continues to render the
-- fallback PROPERTY_TYPE_LABELS map for historical rows (documented
-- pattern in src/shared/constants/property.js).
-- ===========================================================

-- Step 1: soft-deactivate every non-authoritative row (idempotent).
UPDATE master_property_types
   SET is_active = 0,
       deleted_at = COALESCE(deleted_at, NOW())
 WHERE deleted_at IS NULL
   AND code NOT IN (
     'bank_auction',
     'bungalow',
     'commercial_space',
     'flat',
     'hospital',
     'hostel',
     'hotel',
     'industrial_plot',
     'land',
     'plot',
     'pre_leased_property',
     'project_registration',
     'sez_land',
     'sez_plot',
     'shop',
     'tdr'
   );

-- Step 2: upsert each of the 16 authoritative rows.
-- INSERT if the code does not yet exist. If a soft-deleted twin
-- already occupies the (unique) code slot, revive it below via an
-- explicit UPDATE (INSERT IGNORE would silently skip and leave it
-- soft-deleted, which is not what we want).
INSERT IGNORE INTO master_property_types (code, label, sort_order, is_active) VALUES
  ('bank_auction',           'Bank Auction',           10, 1),
  ('bungalow',               'Bungalow',               20, 1),
  ('commercial_space',       'Commercial Space',       30, 1),
  ('flat',                   'Flat',                   40, 1),
  ('hospital',               'Hospital',               50, 1),
  ('hostel',                 'Hostel',                 60, 1),
  ('hotel',                  'Hotel',                  70, 1),
  ('industrial_plot',        'Industrial Plot',        80, 1),
  ('land',                   'Land',                   90, 1),
  ('plot',                   'Plot',                  100, 1),
  ('pre_leased_property',    'Pre-Leased Property',   110, 1),
  ('project_registration',   'Project Registration',  120, 1),
  ('sez_land',               'SEZ Land',              130, 1),
  ('sez_plot',               'SEZ Plot',              140, 1),
  ('shop',                   'Shop',                  150, 1),
  ('tdr',                    'TDR',                   160, 1);

-- Revive-in-place: any of the 16 codes that already exists (either
-- active or soft-deleted) gets its label / sort_order / is_active
-- refreshed to the authoritative values. This is what turns a
-- previously-soft-deleted row (e.g. from an earlier run of this
-- migration on a dev DB) back into an active canonical row without
-- creating a duplicate code.
UPDATE master_property_types SET label = 'Bank Auction',         sort_order = 10,  is_active = 1, deleted_at = NULL WHERE code = 'bank_auction';
UPDATE master_property_types SET label = 'Bungalow',             sort_order = 20,  is_active = 1, deleted_at = NULL WHERE code = 'bungalow';
UPDATE master_property_types SET label = 'Commercial Space',     sort_order = 30,  is_active = 1, deleted_at = NULL WHERE code = 'commercial_space';
UPDATE master_property_types SET label = 'Flat',                 sort_order = 40,  is_active = 1, deleted_at = NULL WHERE code = 'flat';
UPDATE master_property_types SET label = 'Hospital',             sort_order = 50,  is_active = 1, deleted_at = NULL WHERE code = 'hospital';
UPDATE master_property_types SET label = 'Hostel',               sort_order = 60,  is_active = 1, deleted_at = NULL WHERE code = 'hostel';
UPDATE master_property_types SET label = 'Hotel',                sort_order = 70,  is_active = 1, deleted_at = NULL WHERE code = 'hotel';
UPDATE master_property_types SET label = 'Industrial Plot',      sort_order = 80,  is_active = 1, deleted_at = NULL WHERE code = 'industrial_plot';
UPDATE master_property_types SET label = 'Land',                 sort_order = 90,  is_active = 1, deleted_at = NULL WHERE code = 'land';
UPDATE master_property_types SET label = 'Plot',                 sort_order = 100, is_active = 1, deleted_at = NULL WHERE code = 'plot';
UPDATE master_property_types SET label = 'Pre-Leased Property',  sort_order = 110, is_active = 1, deleted_at = NULL WHERE code = 'pre_leased_property';
UPDATE master_property_types SET label = 'Project Registration', sort_order = 120, is_active = 1, deleted_at = NULL WHERE code = 'project_registration';
UPDATE master_property_types SET label = 'SEZ Land',             sort_order = 130, is_active = 1, deleted_at = NULL WHERE code = 'sez_land';
UPDATE master_property_types SET label = 'SEZ Plot',             sort_order = 140, is_active = 1, deleted_at = NULL WHERE code = 'sez_plot';
UPDATE master_property_types SET label = 'Shop',                 sort_order = 150, is_active = 1, deleted_at = NULL WHERE code = 'shop';
UPDATE master_property_types SET label = 'TDR',                  sort_order = 160, is_active = 1, deleted_at = NULL WHERE code = 'tdr';


-- ---------------------------------------------------------------------
-- migration: 059_land_plot_cascade_masters.sql
-- ---------------------------------------------------------------------
-- T-2026-047: Wire parent_code on Land Sub-Type + seed a new Plot Category
-- (Residential) master so Land Type -> Land Sub-Type and Plot Type -> Plot
-- Category dropdowns cascade correctly on both Inventory and Enquiry forms.
--
-- Design:
--   * `land_sub_type` values are shared across four parent categories
--     (Agriculture / Residential / Commercial / Industrial). This migration
--     assigns parent_code to each existing row so /public/masters/land_sub_type?parentCode=X
--     returns only the sub-types for the picked Land Type.
--
--   * `land_category_residential`, `land_category_commercial`,
--     `land_category_industrial` already are per-parent by KEY (not by
--     parent_code), so no changes needed to their rows — the frontend
--     visibleWhen predicate hides the wrong-category rows entirely.
--
--   * Plot Category (Residential) becomes a NEW master vocabulary
--     `plot_category_residential` — replaces the historical inline
--     ['Independent', 'Attached'] radio. Codes are lowercase equivalents
--     of the legacy labels so `coercePlotCategoryValue` (frontend) can
--     translate saved data at load time without a DB backfill.
--
--   * Plot Sub-Type is per-parent by KEY (plot_sub_residential /
--     plot_sub_commercial / plot_sub_industrial) — same as land category
--     above — so no parent_code changes needed on those rows.
--
-- Idempotent: uses INSERT IGNORE for new rows and UPDATE with WHERE for
-- parent_code assignments. Re-running the migration is a no-op after the
-- first successful pass.

-- ────────────────────────────────────────────────────────────────────
-- 1. Assign parent_code to land_sub_type rows
--    Mapping is derived from the existing seed (migration 034):
--    bagayati/jirayati/malran     -> agriculture
--    pure_yellow/gaothan_yellow/proposed_yellow/special_yellow -> residential
--    c1_local/c2_district/sc      -> commercial
--    i1_service/i2_general/i3_special/ie -> industrial
-- ────────────────────────────────────────────────────────────────────

UPDATE master_lookups
SET parent_code = 'agriculture'
WHERE master_key = 'land_sub_type'
  AND code IN ('bagayati', 'jirayati', 'malran')
  AND (parent_code IS NULL OR parent_code = '');

UPDATE master_lookups
SET parent_code = 'residential'
WHERE master_key = 'land_sub_type'
  AND code IN ('pure_yellow', 'gaothan_yellow', 'proposed_yellow', 'special_yellow')
  AND (parent_code IS NULL OR parent_code = '');

UPDATE master_lookups
SET parent_code = 'commercial'
WHERE master_key = 'land_sub_type'
  AND code IN ('c1_local', 'c2_district', 'sc')
  AND (parent_code IS NULL OR parent_code = '');

UPDATE master_lookups
SET parent_code = 'industrial'
WHERE master_key = 'land_sub_type'
  AND code IN ('i1_service', 'i2_general', 'i3_special', 'ie')
  AND (parent_code IS NULL OR parent_code = '');

-- ────────────────────────────────────────────────────────────────────
-- 2. Seed the new plot_category_residential master
--    Two initial values matching the legacy inline radio. Admins can
--    extend this vocabulary from Global Masters > Plot Category.
-- ────────────────────────────────────────────────────────────────────

INSERT IGNORE INTO master_lookups (master_key, code, label, sort_order, is_active) VALUES
  ('plot_category_residential', 'independent', 'Independent', 10, 1),
  ('plot_category_residential', 'attached',    'Attached',    20, 1);

-- ────────────────────────────────────────────────────────────────────
-- 3. Revive-in-place any rows that were soft-deleted before this seed
--    (mirrors T-2026-046 idempotency pattern).
-- ────────────────────────────────────────────────────────────────────

UPDATE master_lookups
SET is_active = 1, deleted_at = NULL, sort_order = 10, label = 'Independent'
WHERE master_key = 'plot_category_residential' AND code = 'independent';

UPDATE master_lookups
SET is_active = 1, deleted_at = NULL, sort_order = 20, label = 'Attached'
WHERE master_key = 'plot_category_residential' AND code = 'attached';


