-- ---------------------------------------------------------------------
-- migration: 064_property_type_reactivate_paying_guest.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 064 - Global / Property Type: reactivate `paying_guest`
-- ===========================================================
-- Migration 058 reseeded master_property_types to 16 authoritative values
-- and soft-deleted every other row. `paying_guest` (originally seeded by
-- migration 012) was among the soft-deleted set.
--
-- The frontend, however, still treats `paying_guest` as a canonical
-- Property Type -- see
-- src/admin/pages/Inventory/dynamic/formCodeCanonicalMap.js:44
--   ['paying-guest-', 'paying_guest']
-- and the four Paying Guest registration forms in
-- src/admin/pages/Inventory/dynamic/payingGuestFormsConfig.js which each
-- ship `propertyType: 'paying_guest'` in the payload. The backend
-- constants map (server/constants/formCodeCatalog.js:PROPERTY_TYPE_TO_PREFIX)
-- also lists `paying_guest`.
--
-- After the ID-first centralised validator went live (services/masters/
-- propertyMasters.js), the previously-silent `propertyType` check became
-- strict, exposing the drift: PG saves failed with
--   "Unknown or inactive global / property type: 'paying_guest'"
--
-- This migration revives the row in place (preserves id + audit history)
-- so PG forms save cleanly. It does NOT touch transaction_type or
-- property_variety masters; `paying_guest` already exists as an active
-- transaction_type (migration 046).
-- ===========================================================

-- Revive an existing soft-deleted row if present.
UPDATE master_property_types
   SET label       = 'Paying Guest',
       sort_order  = 105,
       is_active   = 1,
       deleted_at  = NULL
 WHERE code = 'paying_guest';

-- Or insert fresh if this DB never had the row (idempotent guard).
INSERT IGNORE INTO master_property_types (code, label, sort_order, is_active)
VALUES ('paying_guest', 'Paying Guest', 105, 1);


-- ---------------------------------------------------------------------
-- migration: 065_chooser_tree_master_rows_seed.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 065 - Seed the master rows the chooser tree references
-- ===========================================================
-- T-2026-066: after PropertyTypeChooser.jsx started emitting canonical
-- ptCode / ttCode / pvCode into the URL (so a user's "Paying Guest > Out
-- > Flat" selection can no longer be silently overwritten by form-code
-- projection), every code that appears in the chooser tree must resolve
-- to an active master row so:
--   1. FE save-time guard passes,
--   2. BE validatePropertyClassification passes,
--   3. list/detail APIs return a labelled name for the homepage.
--
-- Codes here are DERIVED FROM CHOOSER TREE LABELS via
-- src/admin/pages/Inventory/PropertyTypeChooser.jsx :: labelToCanonicalCode
-- (lowercase, ASCII-fold, non-alphanumerics -> underscore). The list below
-- is the diff between the chooser labels and the pre-mig-065 master seed
-- (mig 008 / 016 / 021 / 045 / 046 for transaction types; mig 054 for
-- property varieties).
--
-- INSERT IGNORE keeps re-runs safe. UPDATE-revive clauses reactivate any
-- row that was soft-deleted by a prior migration (so hostile
-- upgrade/downgrade cycles converge to the intended state).
-- ===========================================================

-- --------------------- master_transaction_types --------------------------
-- Chooser labels that had no matching TT code pre-065:
--   Buy         -> buy          (Hotel / Enquiry)
--   In          -> in           (TDR / Enquiry)
--   Let In      -> let_in       (Hostel / Enquiry)
--   Let Out     -> let_out      (Hostel / Inventory)
--   Out         -> out          (Paying Guest / Inventory, TDR / Inventory)
--   Rate Finder -> rate_finder  (Flat / Land / Plot / Shop enquiries)
--   Registration-> registration (Project Registration)
--   Sell        -> sell         (Hospital / Hotel / Inventory)
INSERT IGNORE INTO master_transaction_types (code, label, sort_order, is_active) VALUES
  ('buy',          'Buy',           200, 1),
  ('in',           'In',            210, 1),
  ('let_in',       'Let In',        220, 1),
  ('let_out',      'Let Out',       230, 1),
  ('out',          'Out',           240, 1),
  ('rate_finder',  'Rate Finder',   250, 1),
  ('registration', 'Registration',  260, 1),
  ('sell',         'Sell',          270, 1);

-- Revive-in-place if any of these codes was previously soft-deleted.
UPDATE master_transaction_types SET label = 'Buy',          sort_order = 200, is_active = 1, deleted_at = NULL WHERE code = 'buy';
UPDATE master_transaction_types SET label = 'In',           sort_order = 210, is_active = 1, deleted_at = NULL WHERE code = 'in';
UPDATE master_transaction_types SET label = 'Let In',       sort_order = 220, is_active = 1, deleted_at = NULL WHERE code = 'let_in';
UPDATE master_transaction_types SET label = 'Let Out',      sort_order = 230, is_active = 1, deleted_at = NULL WHERE code = 'let_out';
UPDATE master_transaction_types SET label = 'Out',          sort_order = 240, is_active = 1, deleted_at = NULL WHERE code = 'out';
UPDATE master_transaction_types SET label = 'Rate Finder',  sort_order = 250, is_active = 1, deleted_at = NULL WHERE code = 'rate_finder';
UPDATE master_transaction_types SET label = 'Registration', sort_order = 260, is_active = 1, deleted_at = NULL WHERE code = 'registration';
UPDATE master_transaction_types SET label = 'Sell',         sort_order = 270, is_active = 1, deleted_at = NULL WHERE code = 'sell';

-- --------------------- master_lookups (property_variety) -----------------
-- Chooser labels that had no matching PV code pre-065:
--   Bungalow -> bungalow  (Paying Guest / Out / Bungalow)
--   Flat     -> flat      (Paying Guest / Out / Flat)
--
-- These are DELIBERATELY the same slug as some property_type codes -
-- the property_variety master is a SEPARATE vocabulary (mig 054), so the
-- collision is only structural (same string, different table + role).
INSERT IGNORE INTO master_lookups (master_key, code, label, sort_order, is_active) VALUES
  ('property_variety', 'bungalow', 'Bungalow', 100, 1),
  ('property_variety', 'flat',     'Flat',     110, 1);

UPDATE master_lookups SET label = 'Bungalow', sort_order = 100, is_active = 1, deleted_at = NULL
 WHERE master_key = 'property_variety' AND code = 'bungalow';
UPDATE master_lookups SET label = 'Flat',     sort_order = 110, is_active = 1, deleted_at = NULL
 WHERE master_key = 'property_variety' AND code = 'flat';


-- ---------------------------------------------------------------------
-- migration: 066_business_associates_business_fields.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 066 — Business Associates: company_name / business_category
-- ===========================================================
-- Promotes two previously-packed values out of address_line2 into
-- their own columns so the manual Add/Edit form + Bulk Upload can
-- read/write them directly (and the View page can surface them as
-- discrete rows):
--
--   company_name       -- was: bulk-upload "Company Name" packed into
--                        address_line2 as "Co: ...". Rename display
--                        label to "Company Name / Business".
--   business_category  -- NEW column in the enhancement request.
--
-- Both columns are nullable so existing rows stay valid without
-- backfill. Nothing else in the row shape changes.
--
-- NOTE: An earlier revision of this migration also added a `business`
-- column, which was subsequently deemed unnecessary and removed. If a
-- prior apply left that column on your DB, drop it with:
--   ALTER TABLE business_associates DROP COLUMN business;
-- ===========================================================

SET NAMES utf8mb4;

ALTER TABLE business_associates
  ADD COLUMN company_name      VARCHAR(255) NULL AFTER surname,
  ADD COLUMN business_category VARCHAR(255) NULL AFTER company_name;


-- ---------------------------------------------------------------------
-- migration: 067_document_directory.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 067 - Document Directory
-- ===========================================================
-- Standalone Admin module for securely storing, viewing,
-- downloading and sharing business documents. Binary content
-- is written to disk under uploads/private/documents/ - this
-- table stores metadata + the relative storage path.
--
-- No related tables (share history / email queue / audit logs)
-- are created intentionally: email sending is runtime-only per
-- the spec, so nothing about a share is persisted.
--
-- document_id is a human-facing identifier in the form
--   DOC-YY-<7 alnum> (e.g. DOC-26-A7KD92F)
-- generated in the service layer with a uniqueness re-try loop.
-- ===========================================================

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS documents (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  document_id       VARCHAR(32)  NOT NULL,
  document_name     VARCHAR(255) NOT NULL,
  description       TEXT         NULL,
  category          VARCHAR(100) NULL,
  tags              VARCHAR(500) NULL,
  original_filename VARCHAR(500) NOT NULL,
  stored_filename   VARCHAR(255) NOT NULL,
  extension         VARCHAR(32)  NULL,
  mime_type         VARCHAR(255) NULL,
  file_size         BIGINT UNSIGNED NOT NULL DEFAULT 0,
  storage_path      VARCHAR(500) NOT NULL,
  uploaded_by       BIGINT UNSIGNED NULL,
  status            ENUM('active','archived') NOT NULL DEFAULT 'active',
  created_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at        DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted_at        DATETIME NULL,
  PRIMARY KEY (id),
  UNIQUE KEY uq_documents_document_id (document_id),
  KEY ix_documents_created_at (created_at),
  KEY ix_documents_status     (status),
  KEY ix_documents_extension  (extension),
  KEY ix_documents_name       (document_name)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


-- ---------------------------------------------------------------------
-- migration: 068_phone_book.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 068 — Phone Book Database
-- ===========================================================
-- Independent centralized directory for personal + business contacts.
-- Deliberately SEPARATE from `business_associates` — no shared table,
-- no shared APIs, no shared backend implementation. UI-only similarity
-- with the Business Associates page is intentional per product spec.
-- ===========================================================

SET NAMES utf8mb4;

CREATE TABLE IF NOT EXISTS phone_book (
  id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT,
  salutation    ENUM('mr','mrs','miss','smt') NULL,
  first_name    VARCHAR(100) NOT NULL,
  middle_name   VARCHAR(100) NULL,
  surname       VARCHAR(100) NULL,
  company_name  VARCHAR(255) NULL,
  designation   VARCHAR(200) NULL,
  address_line1 VARCHAR(255) NULL,
  address_line2 VARCHAR(255) NULL,
  city_code     VARCHAR(64)  NULL,
  taluka_code   VARCHAR(64)  NULL,
  district_code VARCHAR(64)  NULL,
  phone1        VARCHAR(20)  NULL,
  phone2        VARCHAR(20)  NULL,
  mobile1       VARCHAR(20)  NULL,
  mobile2       VARCHAR(20)  NULL,
  mobile3       VARCHAR(20)  NULL,
  whatsapp      VARCHAR(20)  NULL,
  email1        VARCHAR(255) NULL,
  email2        VARCHAR(255) NULL,
  website1      VARCHAR(255) NULL,
  website2      VARCHAR(255) NULL,
  date_of_birth DATE NULL,
  notes         VARCHAR(500) NULL,
  created_by_admin_id BIGINT UNSIGNED NULL,
  created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  deleted_at DATETIME NULL,
  PRIMARY KEY (id),
  KEY ix_phone_book_district (district_code),
  KEY ix_phone_book_taluka   (taluka_code),
  KEY ix_phone_book_city     (city_code),
  KEY ix_phone_book_created  (created_at),
  KEY ix_phone_book_mobile1  (mobile1),
  KEY ix_phone_book_email1   (email1),
  CONSTRAINT fk_phone_book_admin FOREIGN KEY (created_by_admin_id) REFERENCES admins (id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;


