-- ---------------------------------------------------------------------
-- migration: 074_business_associates_area_property_wise.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 074 — Business Associates: area_wise + property_wise columns
-- ===========================================================
-- T-2026-079: Enhancement request — after the Designation is
-- selected on the Business Associate form, two dependent
-- dropdowns appear below it:
--
--   • area_wise      → Global `location` master (searchable
--                       with the shared "Other → Save → refresh"
--                       flow). Stores the master LABEL for
--                       backward compat with the same rule the
--                       enquiry `location` field follows (see
--                       T-2026-075) — that way a curated Nashik
--                       locality name like "College Road" reads
--                       cleanly on List / View surfaces without
--                       an extra join.
--
--   • property_wise  → Global `property_type` master. Stores
--                       the master CODE (e.g. 'flat', 'plot',
--                       'bungalow') to match how every other
--                       property_type reference on the backend
--                       persists — resolved to a label at read
--                       time via the master lookup on the FE.
--
-- Guardrails:
--   * Additive only. No column dropped or renamed.
--   * Both nullable so pre-existing rows are legal without
--     any backfill.
--   * Idempotent. Second run is a no-op (guarded on
--     information_schema).
--   * No trigger, no view, no procedure. Straight DDL.
-- ===========================================================

-- business_associates.area_wise
SET @col_exists := (
  SELECT COUNT(*) FROM information_schema.columns
  WHERE table_schema = DATABASE()
    AND table_name = 'business_associates'
    AND column_name = 'area_wise'
);
SET @sql := IF(@col_exists = 0,
  'ALTER TABLE business_associates ADD COLUMN area_wise VARCHAR(255) NULL AFTER designation',
  'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- business_associates.property_wise
SET @col_exists := (
  SELECT COUNT(*) FROM information_schema.columns
  WHERE table_schema = DATABASE()
    AND table_name = 'business_associates'
    AND column_name = 'property_wise'
);
SET @sql := IF(@col_exists = 0,
  'ALTER TABLE business_associates ADD COLUMN property_wise VARCHAR(64) NULL AFTER area_wise',
  'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;


-- ---------------------------------------------------------------------
-- migration: 075_enquiry_status_master.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 075 — Enquiry Property Status master (split from status_type)
-- ===========================================================
-- T-2026-080: Split the shared "Property Status" master into
-- two independent vocabularies so Inventory and Enquiry can
-- carry different workflow states.
--
--   * status_type    (existing, master_status_types table)
--       Rename display label to "Inventory / Property Status".
--       Rows: available / sold / rented / inactive
--       + any custom rows the admin has added. UNCHANGED here —
--       label rename lives on the FE/BE registration side, not
--       the DB row itself.
--
--   * enquiry_status (NEW, master_lookups table)
--       Label "Enquiry / Property Status".
--       Seeds 4 defaults (new_enquiry / enquiry_in_discussion /
--       enquiry_converted / enquiry_lost) each with a Description.
--       Legacy codes (available / sold / rented / inactive)
--       are ALSO seeded but flagged INACTIVE so:
--         (a) existing enquiry_properties rows whose status is
--             still one of those legacy codes continue to
--             resolve to a human label on read paths, and
--         (b) the new-enquiry dropdown only offers the 4 new
--             active codes.
--       Admin can hard-delete the legacy inactive rows later
--       once every historical enquiry row has been migrated.
--
-- Guardrails:
--   * Additive only. No column dropped or renamed.
--   * Idempotent. Second run is a no-op (INSERT IGNORE +
--     information_schema-guarded ADD COLUMN).
--   * `master_lookups.description` is added as a nullable
--     column so every existing lookup row stays legal without
--     backfill and every future lookup key can carry a
--     Description/Meaning without another schema bump.
-- ===========================================================

-- Step 1: master_lookups.description
SET @col_exists := (
  SELECT COUNT(*) FROM information_schema.columns
  WHERE table_schema = DATABASE()
    AND table_name = 'master_lookups'
    AND column_name = 'description'
);
SET @sql := IF(@col_exists = 0,
  'ALTER TABLE master_lookups ADD COLUMN description VARCHAR(255) NULL AFTER label',
  'SELECT 1');
PREPARE stmt FROM @sql; EXECUTE stmt; DEALLOCATE PREPARE stmt;

-- Step 2: seed the 4 default active enquiry statuses
--
-- Uses INSERT ... ON DUPLICATE KEY UPDATE so a re-run refreshes the
-- description text without disturbing sort_order / is_active. If an
-- admin has already tweaked one of these rows the label + description
-- get restored to the seeded canonical values (matches the enum-style
-- guarantee for seeded defaults elsewhere in the codebase).
INSERT INTO master_lookups (master_key, code, label, description, sort_order, is_active)
VALUES
  ('enquiry_status', 'new_enquiry',          'New Enquiry',           'Newly received enquiry awaiting processing.',                       10, 1),
  ('enquiry_status', 'enquiry_in_discussion','Enquiry In Discussion', 'Discussion or follow-up is currently in progress.',                 20, 1),
  ('enquiry_status', 'enquiry_converted',    'Enquiry Converted',     'Enquiry has successfully converted into a confirmed deal.',         30, 1),
  ('enquiry_status', 'enquiry_lost',         'Enquiry Lost',          'Enquiry closed without conversion.',                                40, 1)
ON DUPLICATE KEY UPDATE
  label       = VALUES(label),
  description = VALUES(description),
  sort_order  = VALUES(sort_order);

-- Step 3: seed the 4 legacy codes as INACTIVE
--
-- Kept as inactive rows so existing enquiry_properties.status values
-- (which historically shared the inventory status codes) still resolve
-- to a human label on read paths. Not offered in new-enquiry dropdowns.
-- Descriptions are borrowed from the same wording the Inventory master
-- carries so admins reading the row understand the legacy meaning.
INSERT INTO master_lookups (master_key, code, label, description, sort_order, is_active)
VALUES
  ('enquiry_status', 'available', 'Available (legacy)', 'Legacy code inherited from the shared Property Status master. Kept for backward compatibility with older enquiry records.', 90, 0),
  ('enquiry_status', 'sold',      'Sold (legacy)',      'Legacy code inherited from the shared Property Status master. Prefer "Enquiry Converted" for new records.',                91, 0),
  ('enquiry_status', 'rented',    'Rented (legacy)',    'Legacy code inherited from the shared Property Status master. Prefer "Enquiry Converted" for new records.',                92, 0),
  ('enquiry_status', 'inactive',  'Inactive (legacy)',  'Legacy code inherited from the shared Property Status master. Prefer "Enquiry Lost" for new records.',                     93, 0)
ON DUPLICATE KEY UPDATE
  label       = VALUES(label),
  description = VALUES(description),
  sort_order  = VALUES(sort_order);

-- Step 4: migrate existing enquiry_properties rows from legacy inventory
-- codes to the new enquiry-specific codes. Runs after the seeds above so
-- both source and target codes exist in the master. Idempotent — the WHERE
-- clause filters to only the four legacy codes so a re-run after the
-- migration has already promoted every row is a no-op.
--
-- Mapping rationale:
--   available → new_enquiry
--       Enquiry rows default to 'available' on create (schema default from
--       migration 056) which historically meant "just received, awaiting
--       processing". That matches New Enquiry semantics 1:1.
--   sold      → enquiry_converted
--       On the enquiry side a "sold" record represented a converted lead
--       (the deal closed).
--   rented    → enquiry_converted
--       Same rationale as sold — the enquiry converted into a rental deal.
--   inactive  → enquiry_lost
--       An enquiry marked inactive was one closed without conversion.
--
-- Post-migration the four legacy rows above stay in the master as
-- INACTIVE reference rows so any label lookup fired during audit trail
-- rendering still resolves to their (legacy) label.
UPDATE enquiry_properties SET status = 'new_enquiry'       WHERE status = 'available' AND deleted_at IS NULL;
UPDATE enquiry_properties SET status = 'enquiry_converted' WHERE status = 'sold'      AND deleted_at IS NULL;
UPDATE enquiry_properties SET status = 'enquiry_converted' WHERE status = 'rented'    AND deleted_at IS NULL;
UPDATE enquiry_properties SET status = 'enquiry_lost'      WHERE status = 'inactive'  AND deleted_at IS NULL;

-- Step 5: retarget the enquiry_properties.status column default to the new
-- canonical starting state so a fresh INSERT that omits `status` lands as
-- 'new_enquiry' instead of the now-inactive 'available' code.
ALTER TABLE enquiry_properties MODIFY COLUMN status VARCHAR(64) NOT NULL DEFAULT 'new_enquiry';


-- ---------------------------------------------------------------------
-- migration: 076_inventory_status_professional_labels.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 076 — Inventory Property Status: professional labels + descriptions
-- ===========================================================
-- T-2026-082: The Inventory Property Status master (status_type,
-- backed by master_status_types) is being polished:
--
--   * Master DISPLAY LABEL: 'Status Type' → 'Inventory / Property
--     Status'. This lives in server/services/masters/management.js
--     (MASTER_LABELS) and was already renamed in T-2026-080; no DB
--     row change is required for that rename.
--
--   * Per-row labels + descriptions get their client-approved
--     professional wording. Existing IDs preserved — we UPDATE by
--     canonical `code`, never DELETE/INSERT — so every historical
--     inventory_properties.status FK-shaped reference keeps
--     resolving.
--
--   * Two additional codes ('sold_by_me' / 'sold_by_npd') that the
--     client tracks separately from the generic 'sold' state are
--     seeded via INSERT IGNORE so:
--       (a) if they already exist (added earlier by an admin from
--           the master UI) their label + description get refreshed
--           via the UPDATE branch below, and
--       (b) if they don't exist yet, they're created with active=1
--           and a sane sort_order.
--
-- Guardrails:
--   * Additive + idempotent. Second run is a no-op (UPDATE by code
--     is deterministic; INSERT IGNORE deduplicates on the code UK).
--   * NEVER changes the `code` of an existing row — inventory_properties
--     .status stores the code, so a rename would orphan every historical
--     row.
--   * NEVER deletes a row — even if the client later wants to retire
--     a status, they should use the Deactivate button (is_active=0)
--     which the admin UI already exposes.
-- ===========================================================

-- Step 1: update labels + descriptions on the four seeded rows.
UPDATE master_status_types
   SET label = 'Available for Transaction',
       description = 'Property is currently active and available for Sale, Purchase, Rent, Lease or other property transactions.'
 WHERE code = 'available' AND deleted_at IS NULL;

UPDATE master_status_types
   SET label = 'Transaction Completed',
       description = 'The property transaction has been completed and the property is no longer available.'
 WHERE code = 'sold' AND deleted_at IS NULL;

UPDATE master_status_types
   SET label = 'Rented Out',
       description = 'Property has been rented/leased and is currently occupied.'
 WHERE code = 'rented' AND deleted_at IS NULL;

UPDATE master_status_types
   SET label = 'Inactive',
       description = 'Property listing is temporarily inactive and not available for transactions.'
 WHERE code = 'inactive' AND deleted_at IS NULL;

-- Step 2: ensure the two owner/agency-attribution codes exist. Codes are
-- underscored ASCII to match how the master admin's codeFromLabel derives
-- codes (see server/services/masters/management.js codeFromLabel: lowercase,
-- non-alphanum → '-', prefix/suffix '-' stripped). Historical admin-created
-- rows would carry the same code; INSERT IGNORE hits the (code) UK on those
-- and skips. Sort orders slot in after the existing four (10/20/30/40) so
-- the dropdown reads: Available → Transaction Completed → Sold by Owner →
-- Sold by NPD → Rented Out → Inactive.
INSERT IGNORE INTO master_status_types (code, label, description, sort_order, is_active) VALUES
  ('sold_by_me',  'Sold by Owner',                'Property has been sold directly by the owner without Nashik Property Deals handling the transaction.', 25, 1),
  ('sold_by_npd', 'Sold by Nashik Property Deals', 'Property transaction has been successfully completed through Nashik Property Deals.',                 26, 1);

-- Step 3: refresh label + description for the two codes above in case an
-- older admin-created row already exists with an outdated label. Runs
-- after INSERT IGNORE so both freshly-inserted and pre-existing rows
-- converge on the client-approved wording.
UPDATE master_status_types
   SET label = 'Sold by Owner',
       description = 'Property has been sold directly by the owner without Nashik Property Deals handling the transaction.',
       sort_order = 25
 WHERE code = 'sold_by_me' AND deleted_at IS NULL;

UPDATE master_status_types
   SET label = 'Sold by Nashik Property Deals',
       description = 'Property transaction has been successfully completed through Nashik Property Deals.',
       sort_order = 26
 WHERE code = 'sold_by_npd' AND deleted_at IS NULL;


-- ---------------------------------------------------------------------
-- migration: 077_hospital_buy_resale_variety.sql
-- ---------------------------------------------------------------------
-- ===========================================================
-- 077 — Hospital Buy: assign Resale property variety
-- ===========================================================
-- The `hospital-resale` form (Enquiry side, Hospital → Buy) was
-- originally seeded in migration 063 with property_variety_code
-- NULL, so the chooser skipped the variety step in the UI. The
-- reference spec (`reference of forms/Hospital Registration
-- Form.md`) titles this form "Hospital Registration Form[Re-Sale]"
-- and the FE `chooserTree.js` now wraps it in a single-option
-- Resale variety picker to match the other buy-only-Resale forms
-- (bank-auction-resale, industrial-plot-resale, pre-leased-resale,
-- project-resale).
--
-- This migration aligns master_property_forms with that spec so
-- the DB catalog (source of truth once seeded — see T-2026-058
-- and hooks/usePropertyCatalog.js) surfaces the same Resale
-- variety.
--
-- Idempotent: UPDATE by (form_code, mode) unique key. Safe to
-- re-run; safe to run before or after the FE change is deployed
-- (the FE has always accepted the tree either way).
-- ===========================================================

UPDATE master_property_forms
