-- Run these in phpMyAdmin after import to verify everything is present.
-- =====================================================================

-- 1. Confirm database charset/collation
SELECT
  SCHEMA_NAME,
  DEFAULT_CHARACTER_SET_NAME,
  DEFAULT_COLLATION_NAME
FROM information_schema.SCHEMATA
WHERE SCHEMA_NAME = 'nashik_property_deals';

-- 2. Count of tables created
SELECT COUNT(*) AS total_tables
FROM information_schema.TABLES
WHERE TABLE_SCHEMA = 'nashik_property_deals'
  AND TABLE_TYPE = 'BASE TABLE';

-- 3. Every table with row count
SELECT
  TABLE_NAME,
  ENGINE,
  TABLE_ROWS,
  TABLE_COLLATION
FROM information_schema.TABLES
WHERE TABLE_SCHEMA = 'nashik_property_deals'
  AND TABLE_TYPE = 'BASE TABLE'
ORDER BY TABLE_NAME;

-- 4. Foreign key count
SELECT COUNT(*) AS total_foreign_keys
FROM information_schema.TABLE_CONSTRAINTS
WHERE TABLE_SCHEMA = 'nashik_property_deals'
  AND CONSTRAINT_TYPE = 'FOREIGN KEY';

-- 5. Confirm every migration is recorded as applied
SELECT COUNT(*) AS migrations_recorded FROM schema_migrations;
SELECT filename FROM schema_migrations ORDER BY filename;

-- 6. Spot-check seed data (master lookup tables)
SELECT 'master_property_types'    AS master, COUNT(*) AS rows_seeded FROM master_property_types
UNION ALL SELECT 'master_transaction_types',    COUNT(*) FROM master_transaction_types
UNION ALL SELECT 'master_lookups',              COUNT(*) FROM master_lookups
UNION ALL SELECT 'master_property_forms',       COUNT(*) FROM master_property_forms;

